:root {
  /* Define a base fluid font size for the body */
  --body-fluid-font-size: clamp(1rem, 0.8rem + 0.8vw, 1.25rem);
  /* Example for a heading, even more dynamic */
  --h1-fluid-font-size: clamp(2rem, 1.5rem + 3vw, 4rem);
}

body {
  font-size: var(--body-fluid-font-size);
}

h1 {
  font-size: var(--h1-fluid-font-size);
}
